B.ac3=new A.dq([B.cU,"Spoel je glas eerst koud om","Een koud gespoeld glas zorgt voor een mooiere schuimkraag en voorkomt dat je bier te snel opwarmt.",null,"BierKompas",null])
B.abH=new A.dq([B.cx,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.abZ=new A.dq([B.cw,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.abJ=new A.dq([B.cU,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.abP=new A.dq([B.cx,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.abQ=new A.dq([B.cw,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.ac6=new A.dq([B.cU,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.ac5=new A.dq([B.cx,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
B.abY=new A.dq([B.cw,"Zomerhaven Witbier","Troebel, met citrus en koriander. Iets te zoet naar mijn smaak, maar heerlijk als het buiten 25 graden is.",u.c,"Daan",3.5])
B.abV=new A.dq([B.cU,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.abR=new A.dq([B.cx,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
